cards.example:
server {
  listen 443 ssl;
  server_name api.example.com;
  location / {
    proxy_pass http://app_upstream;
    proxy_set_header X-Real-IP $remote_addr;
  }
}

proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
proxy_set_header X-Real-IP $remote_addr;

# в приложении читаем X-Forwarded-For, но только от доверенного прокси

upstream app {
  server 10.0.1.10:8000;
  keepalive 32;
}
# в приложении: pool_size=20, max_overflow=10, timeout=5s
